Here is the root cause:
In virtbt_rx_work(), the length 'len' returned from virtqueue_get_buf() is not validated against the actual buffer size (1000) before being passed to skb_put(). This allows a malicious or buggy backend to report a length larger than the buffer, causing skb_put() to extend the skb into uninitialized kernel heap memory, or a length of 0 which causes virtbt_rx_handle() to read uninitialized data from skb->data.

Here is the patch:

 #define VERSION "0.1"
+#define VIRTBT_RX_BUF_SIZE 1000

 enum {

 static int virtbt_add_inbuf(struct virtio_bluetooth *vbt)
 {
 	struct virtqueue *vq = vbt->vqs[VIRTBT_VQ_RX];
 	struct scatterlist sg[1];
 	struct sk_buff *skb;
 	int err;

-	skb = alloc_skb(1000, GFP_KERNEL);
+	skb = alloc_skb(VIRTBT_RX_BUF_SIZE, GFP_KERNEL);
 	if (!skb)
 		return -ENOMEM;

-	sg_init_one(sg, skb->data, 1000);
+	sg_init_one(sg, skb->data, VIRTBT_RX_BUF_SIZE);

 	err = virtqueue_add_inbuf(vq, sg, 1, skb, GFP_KERNEL);
 	if (err < 0) {
 		kfree_skb(skb);
 		return err;
 	}

 	return 0;
 }


 static void virtbt_rx_work(struct work_struct *work)
 {
 	struct virtio_bluetooth *vbt = container_of(work,
 						    struct virtio_bluetooth, rx);
 	struct sk_buff *skb;
 	unsigned int len;

 	skb = virtqueue_get_buf(vbt->vqs[VIRTBT_VQ_RX], &len);
 	if (!skb)
 		return;

-	skb_put(skb, len);
-	virtbt_rx_handle(vbt, skb);
+	if (!len || len > VIRTBT_RX_BUF_SIZE) {
+		bt_dev_err_ratelimited(vbt->hdev,
+				       "rx reply len %u outside [1, %u]\n",
+				       len, VIRTBT_RX_BUF_SIZE);
+		kfree_skb(skb);
+	} else {
+		skb_put(skb, len);
+		virtbt_rx_handle(vbt, skb);
+	}

 	if (virtbt_add_inbuf(vbt) < 0)
 		return;

 	virtqueue_kick(vbt->vqs[VIRTBT_VQ_RX]);
 }



